PRAGMA foreign_keys=ON;
CREATE TABLE commerce_products(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchants(id),title TEXT NOT NULL,slug TEXT NOT NULL,product_type TEXT NOT NULL CHECK(product_type IN('physical','digital','service','preorder')),status TEXT NOT NULL DEFAULT 'draft',description TEXT,seo_json TEXT NOT NULL DEFAULT '{}',member_only INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,allow_backorder INTEGER NOT NULL DEFAULT 0,publish_at TEXT,unpublish_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,slug),UNIQUE(merchant_id,id));
CREATE TABLE commerce_product_variants(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,product_id TEXT NOT NULL,sku TEXT,barcode TEXT,title TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>=0),compare_at_minor INTEGER,cost_minor INTEGER,member_price_minor INTEGER,weight_grams INTEGER NOT NULL DEFAULT 0,dimensions_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,sku),UNIQUE(merchant_id,id),FOREIGN KEY(merchant_id,product_id) REFERENCES commerce_products(merchant_id,id));
CREATE TABLE commerce_product_options(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,product_id TEXT NOT NULL,name TEXT NOT NULL,sort_order INTEGER NOT NULL,FOREIGN KEY(merchant_id,product_id) REFERENCES commerce_products(merchant_id,id));
CREATE TABLE commerce_product_option_values(id TEXT PRIMARY KEY,option_id TEXT NOT NULL REFERENCES commerce_product_options(id),value TEXT NOT NULL,sort_order INTEGER NOT NULL);
CREATE TABLE commerce_variant_option_values(variant_id TEXT NOT NULL REFERENCES commerce_product_variants(id),option_value_id TEXT NOT NULL REFERENCES commerce_product_option_values(id),PRIMARY KEY(variant_id,option_value_id));
CREATE TABLE commerce_product_images(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,product_id TEXT NOT NULL,variant_id TEXT,url TEXT NOT NULL,alt_text TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(merchant_id,product_id) REFERENCES commerce_products(merchant_id,id));
CREATE TABLE commerce_collections(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,title TEXT NOT NULL,slug TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',UNIQUE(merchant_id,slug));
CREATE TABLE commerce_collection_products(collection_id TEXT NOT NULL REFERENCES commerce_collections(id),product_id TEXT NOT NULL REFERENCES commerce_products(id),sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(collection_id,product_id));
CREATE TABLE commerce_inventory_locations(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,UNIQUE(merchant_id,id));
CREATE TABLE commerce_inventory_items(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,variant_id TEXT NOT NULL,location_id TEXT NOT NULL,on_hand INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,safety_stock INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,variant_id,location_id),FOREIGN KEY(merchant_id,variant_id) REFERENCES commerce_product_variants(merchant_id,id),FOREIGN KEY(merchant_id,location_id) REFERENCES commerce_inventory_locations(merchant_id,id),CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand));
CREATE TABLE commerce_inventory_movements(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,inventory_item_id TEXT NOT NULL REFERENCES commerce_inventory_items(id),movement_type TEXT NOT NULL,quantity INTEGER NOT NULL,reference_type TEXT,reference_id TEXT,idempotency_key TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key));
CREATE TABLE commerce_stock_reservations(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,inventory_item_id TEXT NOT NULL REFERENCES commerce_inventory_items(id),cart_id TEXT,order_id TEXT,quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL CHECK(status IN('active','consumed','released','expired')),expires_at TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key));
CREATE TRIGGER trg_inventory_movement_immutable_update BEFORE UPDATE ON commerce_inventory_movements BEGIN SELECT RAISE(ABORT,'inventory movement immutable'); END;
CREATE TRIGGER trg_inventory_movement_immutable_delete BEFORE DELETE ON commerce_inventory_movements BEGIN SELECT RAISE(ABORT,'inventory movement immutable'); END;
CREATE INDEX idx_products_public ON commerce_products(merchant_id,status,publish_at,unpublish_at);
